#!/usr/bin/env python3
"""Generate data/seccomp-x86_64.json; never edit the generated profile by hand.

Run with no arguments to fetch the pinned source, or --source FILE to work offline.
--check compares generated bytes with the checked-in profile without writing it.
See docs/runtime.md#syscall-policy for resolution, provenance and update requirements.
"""
import argparse
import hashlib
import json
from pathlib import Path
import urllib.request

# Moby v28.3.3, profiles/seccomp/default.json (Apache-2.0; data/LICENSE.seccomp).
# SHA-256: 01536f1d1df938ae611eba20d6349e0de7a99b6ecdee1549427a0b01b8301e28
SOURCE_URL = "https://raw.githubusercontent.com/moby/moby/v28.3.3/profiles/seccomp/default.json"
SOURCE_SHA256 = "01536f1d1df938ae611eba20d6349e0de7a99b6ecdee1549427a0b01b8301e28"
OUTPUT = Path(__file__).resolve().parent.parent / "data/seccomp-x86_64.json"
IO_URING = ["io_uring_setup", "io_uring_enter", "io_uring_register"]


# Resolve upstream conditions for native amd64, empty capabilities and Linux >= 4.8.
# The worker requires cgroup.kill (Linux 5.14+), so the upstream 4.8 condition always holds.
def selected(rule):
    include, exclude = rule.get("includes", {}), rule.get("excludes", {})
    for condition in (include, exclude):
        assert not set(condition) - {"arches", "caps", "minKernel"}, condition
        assert condition.get("minKernel", "4.8") == "4.8", condition
    if "amd64" in exclude.get("arches", []) or exclude.get("minKernel"):
        return False
    if include.get("arches") and "amd64" not in include["arches"]:
        return False
    # No excluded capability is held, and no required capability is held.
    return not include.get("caps")


# Preserve Docker's selected rules and argument comparisons, adding only the CRIU guards.
# Architecture conditions refer to the native process, not every compatible subarchitecture.
def resolve(source):
    assert source["defaultAction"] == "SCMP_ACT_ERRNO" and source["defaultErrnoRet"] == 1
    arch = next(a for a in source["archMap"] if a["architecture"] == "SCMP_ARCH_X86_64")
    rules = []
    for original in source["syscalls"]:
        if not selected(original):
            continue
        assert not set(original) - {"names", "action", "errnoRet", "args", "includes", "excludes", "comment"}, original
        rule = {key: value for key, value in original.items() if key in ("names", "action", "errnoRet", "args")}
        rule["names"] = [name for name in rule["names"] if name not in IO_URING]
        if "socket" in rule["names"]:
            # Preserve AF_VSOCK's exclusion, AND exclude MPTCP from the socket allow rule.
            assert rule["names"] == ["socket"] and rule["action"] == "SCMP_ACT_ALLOW"
            assert rule["args"] == [{"index": 0, "value": 40, "op": "SCMP_CMP_NE"}]
            rule["args"] = rule["args"] + [{"index": 2, "value": 262, "op": "SCMP_CMP_NE"}]
        if rule["names"]:
            rules.append(rule)
    rules.extend([
        {"names": IO_URING, "action": "SCMP_ACT_ERRNO", "errnoRet": 38},
        {"names": ["socket"], "action": "SCMP_ACT_ERRNO", "errnoRet": 93,
         "args": [{"index": 2, "value": 262, "op": "SCMP_CMP_EQ"}]},
    ])
    return {"defaultAction": source["defaultAction"], "defaultErrnoRet": source["defaultErrnoRet"],
            "architectures": [arch["architecture"], *arch["subArchitectures"]], "syscalls": rules}


# Verify the pinned input before generating or comparing the deterministic OCI profile.
def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, help="Local copy of the pinned upstream JSON (no network)")
    parser.add_argument("--check", action="store_true", help="Fail if the generated file differs")
    args = parser.parse_args()
    if args.source:
        raw = args.source.read_bytes()
    else:
        with urllib.request.urlopen(SOURCE_URL, timeout=30) as response:
            raw = response.read(1 << 20)
    if hashlib.sha256(raw).hexdigest() != SOURCE_SHA256:
        raise SystemExit("upstream seccomp SHA-256 mismatch")
    generated = (json.dumps(resolve(json.loads(raw)), indent=2) + "\n").encode()
    if args.check:
        if OUTPUT.read_bytes() != generated:
            raise SystemExit("generated seccomp profile differs; regenerate it")
        print("PASS generated seccomp profile matches pinned source")
    else:
        OUTPUT.parent.mkdir(exist_ok=True)
        OUTPUT.write_bytes(generated)
        print("Generated", OUTPUT.name, hashlib.sha256(generated).hexdigest())


if __name__ == "__main__":
    main()
